const savedLanguage=localStorage.getItem('sezon-language');
let LANG=['ky','ru','en'].includes(savedLanguage)?savedLanguage:'ru';
const t=value=>{const row=TEXT[value];return Array.isArray(row)?row[{ky:0,ru:1,en:2}[LANG]]:row&&typeof row==='object'?row[LANG]||value:value};
const textSources=new WeakMap(),attributeSources=new WeakMap(),pageTextIds=new WeakMap(),pageAttributeIds=new WeakMap();
const PAGE_CONTENT_KEY='sezon-page-content',PAGE_CONTENT_ROOTS=['top','info','equipment','rules','preparation','onlineRules','phonogramRules','weddingRecording','about','works','book','team','contacts','siteFooter'];
const PAGE_CONTENT_SKIP=new Set(['cv','vn','admin','tm','equipmentList','equipmentEmpty','equipmentAdminList','tl','gf','qc','nt','pk','subs','gen','steps','sd','tot','dg','slots','msg','siteNavigation','languageSelect','mqi','homeMusicToggle','musicNotice']);
let PAGE_CONTENT={ky:{},ru:{},en:{}},pageContentFields=[];
function loadPageContent(){try{const saved=JSON.parse(localStorage.getItem(PAGE_CONTENT_KEY)||'{}');['ky','ru','en'].forEach(lang=>{if(saved[lang]&&typeof saved[lang]==='object')PAGE_CONTENT[lang]=saved[lang]})}catch(error){console.error('Не удалось загрузить сохранённые тексты страниц:',error)}}
function skippedPageContent(node,root){for(let element=node.nodeType===1?node:node.parentElement;element&&element!==root;element=element.parentElement)if(PAGE_CONTENT_SKIP.has(element.id)||element.matches('svg,canvas,script,style,template')||node.nodeType===3&&element.matches('.num'))return true;return false}
function indexPageContent(){pageContentFields=[];PAGE_CONTENT_ROOTS.forEach(page=>{const root=page==='siteFooter'?document.querySelector('footer'):page==='top'?$('hero'):$(page);if(!root)return;let textIndex=0,attributeIndex=0;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);while(walker.nextNode()){const node=walker.currentNode;if(!node.nodeValue.trim()||skippedPageContent(node,root))continue;const id=page+':text:'+textIndex++;pageTextIds.set(node,id);pageContentFields.push({id,page,node,source:node.nodeValue.trim(),kind:'text'})}root.querySelectorAll('[placeholder],[aria-label],[title],[href],[data-n],[data-s]').forEach(element=>{if(skippedPageContent(element,root))return;['placeholder','aria-label','title','href','data-n','data-s'].forEach(attribute=>{if(!element.hasAttribute(attribute))return;const id=page+':attr:'+attributeIndex++;let ids=pageAttributeIds.get(element);if(!ids){ids={};pageAttributeIds.set(element,ids)}ids[attribute]=id;pageContentFields.push({id,page,element,attribute,source:element.getAttribute(attribute),kind:'attribute'})})})})}
function pageContentValue(id,lang){return Object.prototype.hasOwnProperty.call(PAGE_CONTENT[lang]||{},id)?PAGE_CONTENT[lang][id]:null}
function translatePage(){document.documentElement.lang=LANG;document.title=LANG==='ky'?'@Nurmat_mn — үн жаздыруу студиясы':LANG==='ru'?'@Nurmat_mn — студия звукозаписи':'@Nurmat_mn — recording studio';const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);while(walker.nextNode()){const node=walker.currentNode;if(!textSources.has(node))textSources.set(node,node.nodeValue);const source=textSources.get(node),key=source.trim(),override=pageTextIds.has(node)?pageContentValue(pageTextIds.get(node),LANG):null,translated=override===null?t(key):override;if(translated!==key||override!==null){const start=source.match(/^\s*/)[0],end=source.match(/\s*$/)[0];node.nodeValue=start+translated+end}else node.nodeValue=source}document.querySelectorAll('[placeholder],[aria-label],[title],[href],[data-n],[data-s]').forEach(node=>{let attrs=attributeSources.get(node);if(!attrs){attrs={};attributeSources.set(node,attrs)}['placeholder','aria-label','title','href','data-n','data-s'].forEach(name=>{if(!node.hasAttribute(name))return;if(!(name in attrs))attrs[name]=node.getAttribute(name);const ids=pageAttributeIds.get(node),override=ids&&pageContentValue(ids[name],LANG);node.setAttribute(name,override===null||override===undefined?t(attrs[name]):override)})});document.querySelectorAll('.num[data-n]').forEach(node=>{const value=Number(node.dataset.n);if(Number.isFinite(value)){const text=String(Math.round(value))+(node.dataset.s||'');if(node.firstChild)node.firstChild.nodeValue=text;else node.append(document.createTextNode(text))}});const select=$('languageSelect');if(select)select.value=LANG}
function renderPageContentEditor(){const select=$('contentPage'),type=$('contentType'),fields=$('contentFields');if(!select||!fields)return;const page=select.value,headingsOnly=type&&type.value==='headings';fields.innerHTML='';pageContentFields.filter(field=>field.page===page&&(!headingsOnly||field.kind==='text'&&field.node.parentElement&&field.node.parentElement.closest('h1,h2,h3,h4,h5,h6'))).forEach((field,index)=>{const label=document.createElement('label'),numeric=field.kind==='attribute'&&field.attribute==='data-n',input=numeric?document.createElement('input'):document.createElement('textarea'),liveText=field.kind==='text'&&field.node.parentElement,tile=liveText&&field.node.parentElement.closest('.tile'),tileTitle=tile&&tile.querySelector('b'),tileField=tile?`Карточка «${tileTitle?tileTitle.textContent.trim():'главная страница'}» — ${tileTitle===field.node.parentElement?'название':'описание'}`:null,heading=liveText&&field.node.parentElement.closest('h1,h2,h3,h4,h5,h6');label.textContent=`${index+1}. ${heading?'Заголовок: '+heading.textContent.trim():tileField|| (field.kind==='attribute'?field.attribute:liveText?field.node.parentElement.tagName.toLowerCase():'текст')}`;if(numeric){input.type='number';input.min='0';input.step='1';input.required=true}else input.rows=field.kind==='text'&&field.source.length>120?4:2;input.dataset.contentId=field.id;input.value=field.kind==='text'?(liveText?field.node.nodeValue.trim():t(field.source)):field.element.getAttribute(field.attribute);fields.append(label,input)})}
async function savePageContent(){const values={...(PAGE_CONTENT[LANG]||{})},inputs=$('contentFields').querySelectorAll('[data-content-id]');for(const input of inputs){if(input.type==='number'&&(!Number.isSafeInteger(input.valueAsNumber)||input.valueAsNumber<0)){$('contentStatus').textContent='Введите для показателя целое число не меньше нуля.';input.focus();return}values[input.dataset.contentId]=input.value.trim()}const next={...PAGE_CONTENT,[LANG]:values};try{if(!DB)throw new Error('База данных недоступна.');await DB.doc('siteContent/pageContent').set(next);localStorage.setItem(PAGE_CONTENT_KEY,JSON.stringify(next));PAGE_CONTENT=next;translatePage();renderPageContentEditor();$('contentStatus').textContent='Тексты сохранены.'}catch(error){console.error('Не удалось сохранить тексты страниц:',error);$('contentStatus').textContent='Не удалось сохранить тексты: '+(error.message||error.code||'ошибка хранилища')}}
async function resetPageContent(){if(!confirm('Вернуть исходный текст для этой страницы?'))return;const page=$('contentPage').value,values={...(PAGE_CONTENT[LANG]||{})};pageContentFields.filter(field=>field.page===page).forEach(field=>delete values[field.id]);const next={...PAGE_CONTENT,[LANG]:values};try{if(!DB)throw new Error('База данных недоступна.');await DB.doc('siteContent/pageContent').set(next);localStorage.setItem(PAGE_CONTENT_KEY,JSON.stringify(next));PAGE_CONTENT=next;translatePage();renderPageContentEditor();$('contentStatus').textContent='Исходные тексты восстановлены.'}catch(error){console.error('Не удалось восстановить исходные тексты:',error);$('contentStatus').textContent='Не удалось восстановить тексты: '+(error.message||error.code||'ошибка хранилища')}}
loadPageContent();
