const PRICE_KEY='sezon-price-data',DEFAULT_PRICE_DATA=JSON.stringify({packages:PK,options:SUB});
function applyPriceData(data){if(!data||!Array.isArray(data.packages)||!Array.isArray(data.options))return;const validPackages=data.packages.filter(item=>item&&typeof item.id==='string'&&typeof item.n==='string'&&Number.isFinite(+item.min)&&Number.isFinite(+item.max)&&Array.isArray(item.l));const validOptions=data.options.filter(item=>item&&typeof item.id==='string'&&typeof item.n==='string'&&Number.isFinite(+item.min)&&Number.isFinite(+item.max));if(!validPackages.length)return;PK.splice(0,PK.length,...validPackages);SUB.splice(0,SUB.length,...validOptions)}
