function priceItem(){const key=$('priceEntry').value;if(key.startsWith('sub:'))return{type:'sub',item:SUB.find(entry=>entry.id===key.slice(4))};return{type:'package',item:PK.find(entry=>entry.id===key.slice(4))}}
