function imageDataUrl(file){return new Promise((resolve,reject)=>{const image=new Image(),url=URL.createObjectURL(file);image.onload=()=>{URL.revokeObjectURL(url);try{const scale=Math.min(1,1200/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const context=canvas.getContext('2d');if(!context)throw new Error('Не удалось обработать изображение.');context.drawImage(image,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.72);if(data.length>850000)throw new Error('Изображение слишком большое. Выберите фото меньшего размера.');resolve(data)}catch(error){reject(error)}};image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Не удалось обработать изображение.'))};image.src=url})}
function fileDataUrl(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>typeof reader.result==='string'?resolve(reader.result):reject(new Error('Не удалось прочитать файл.'));reader.onerror=()=>reject(reader.error||new Error('Не удалось прочитать файл.'));reader.readAsDataURL(file)})}
function getAudioDuration(file){return new Promise((resolve,reject)=>{const audio=new Audio(),url=URL.createObjectURL(file),timer=setTimeout(()=>finish(new Error('Не удалось определить длительность аудиофайла.')),15000);let settled=false;function finish(error,duration){if(settled)return;settled=true;clearTimeout(timer);audio.removeAttribute('src');URL.revokeObjectURL(url);if(error)reject(error);else resolve(duration)}audio.preload='metadata';audio.onloadedmetadata=()=>{const duration=audio.duration;if(!Number.isFinite(duration)||duration<=0)finish(new Error('Не удалось определить длительность аудиофайла.'));else finish(null,duration)};audio.onerror=()=>finish(new Error('Не удалось прочитать аудиофайл.'));audio.src=url})}
