function idb(){return new Promise((ok,no)=>{try{const q=indexedDB.open('sr',3);q.onupgradeneeded=()=>{const d=q.result;if(!d.objectStoreNames.contains('s'))d.createObjectStore('s',{keyPath:'id',autoIncrement:true});if(!d.objectStoreNames.contains('p'))d.createObjectStore('p');if(!d.objectStoreNames.contains('equipment'))d.createObjectStore('equipment',{keyPath:'id'});if(!d.objectStoreNames.contains('news'))d.createObjectStore('news',{keyPath:'id'})};q.onsuccess=()=>ok(q.result);q.onerror=()=>no(q.error)}catch(e){no(e)}})}
function ix(st,mode,fn){return idb().then(d=>new Promise((ok,no)=>{const r=fn(d.transaction(st,mode).objectStore(st));r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error)}))}
