async function updateSong(item,title,artist,genre){const id=String(item.id),values={title:title.trim(),artist:artist.trim(),genre:genre.trim()};if(!values.title){$('songStatus').textContent='Укажите название песни.';return}try{if(item.local){throw new Error('Локальные песни нельзя синхронизировать. Добавьте аудиофайл через админ-зал.')}else if(SH.some(track=>String(track.id)===id)&&DB){await DB.doc('tracks/'+id).set({...item,...values});SH=SH.map(track=>String(track.id)===id?{...track,...values}:track)}else SONG_SETTINGS.meta[id]=values;if(!await saveSongSettings())return;mix();$('songStatus').textContent='Данные песни сохранены.'}catch(error){console.error('Не удалось сохранить песню:',error);$('songStatus').textContent='Не удалось сохранить песню: '+(error.message||error.code||'ошибка хранилища')}}
