async function addSong(event){event.preventDefault();const title=$('songTitle').value.trim(),artist=$('songArtist').value.trim(),genre=$('songGenre').value.trim(),file=$('songFile').files[0],button=$('songSave');if(TR.length>=MAX_SONGS){$('songStatus').textContent=phrase('Максимум 8 песен. Удалите песню, чтобы добавить другую.','Максимум 8 песен. Удалите песню, чтобы добавить другую.','Maximum 8 songs. Delete a song to add another.');updateSongLimit();return}if(!title||!file){$('songStatus').textContent='Укажите название и выберите аудиофайл.';return}if(!file.type.startsWith('audio/')){$('songStatus').textContent='Выберите аудиофайл.';return}if(file.size>MAX_AUDIO_BYTES){$('songStatus').textContent='Размер аудиофайла должен быть не больше 700 КБ.';return}button.disabled=true;try{if(!DB)throw new Error('База данных недоступна.');const duration=await getAudioDuration(file);if(duration>MAX_AUDIO_SECONDS+AUDIO_DURATION_TOLERANCE_SECONDS){$('songStatus').textContent='Определённая длительность — '+duration.toFixed(2)+' сек. Максимум — 40 секунд; проверьте, не длиннее ли запись.';return}const data=await fileDataUrl(file),id='track-'+Date.now().toString(36);const song={id,title,artist,genre,url:data,at:Date.now()};await DB.doc('tracks/'+id).set(song);SH.push(song);mix();$('songForm').reset();$('songStatus').textContent='Песня добавлена.'}catch(error){console.error('Не удалось добавить песню:',error);$('songStatus').textContent='Не удалось добавить песню: '+(error.message||error.code||'ошибка хранилища')}finally{button.disabled=false;updateSongLimit()}}
